/**
 * Where each station sits on the schematic map, and what connects to what.
 *
 * Generated by `bun run railmap` from the anchors hand-set in that script.
 * Coordinates are grid squares, x rightwards and y down; the renderer scales
 * them. To move a station, move it *there* rather than here - an edit to this
 * file is overwritten the next time anyone runs the script, and the script is
 * also what checks the move has not bent the segments either side of it or
 * slid it on top of a neighbour.
 *
 * Generated 2026-08-30.
 */

export type Land = "lantau" | "island" | "mainland";

/** The one line code that is not a railway line: the whole light rail network. */
export const LIGHT_RAIL = "LR";

export interface MapStation {
  /** Station code, the same id the route database uses. */
  id: string;
  x: number;
  y: number;
  /** Which landmass it stands on. */
  land: Land;
  /** Lines calling here, in the railway's own map order; `LIGHT_RAIL` last. */
  lines: string[];
  /** Light rail routes calling here, by number. Empty where none do. */
  routes: string[];
  /** The light rail's own id for this place, where its routes call. */
  lightRail?: string;
}

/** One grid square, in the units the coordinates below are given in. */
export const GRID = 1;

